mapper.select:
SELECT u.id, u.username, u.name, u.phone, u.email, u.avatar, u.type, u.auth_charging_station AS authChargingStation, u.auth_vehicle AS authVehicle, u.points, u.balance, u.is_deleted AS isDeleted, u.create_time AS createTime, u.last_login_time AS lastLoginTime FROM user_info u WHERE 1 = 1
AND (u.username LIKE CONCAT('%', #{keyword}, '%') OR u.name LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%'))
AND u.type = #{type}
AND u.auth_charging_station = #{authChargingStation}
AND u.auth_vehicle = #{authVehicle}
AND u.create_time >= #{startTime}
AND u.create_time <= #{endTime}
ORDER BY u.create_time DESC

SELECT COUNT(*) > 0
FROM user_info
WHERE id = #{id}
